.root {
  display: flex;
  align-items: flex-start;
  gap: 12px;
}

.start {
  flex-direction: row-reverse;
  justify-content: space-between;
}

.track {
  position: relative;
  flex-shrink: 0;
  width: 40px;
  height: 24px;
  padding: 0;
  border: 0;
  border-radius: var(--r-sm);
  background: rgba(var(--rgb-brand-deep), 0.14);
  box-shadow: inset 0 1px 2px rgba(var(--rgb-contact), 0.14), inset 0 0 0 1px rgba(var(--rgb-brand-deep), 0.12);
  transition:
    background-color var(--dur) var(--ease),
    box-shadow var(--dur) var(--ease);
}

.track:hover:not(:disabled) {
  background: rgba(var(--rgb-brand-deep), 0.2);
}

.on {
  background: var(--brand-gradient);
  box-shadow: var(--glow-sm);
}

.on:hover:not(:disabled) {
  background: var(--brand-gradient);
  box-shadow: var(--glow-md);
}

.track:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.thumb {
  position: absolute;
  top: 3px;
  left: 3px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  border-radius: var(--r-flat, 5px);
  background: var(--surface-solid);
  box-shadow: 0 1px 3px rgba(var(--rgb-contact), 0.25), var(--shadow-specular);
  transition: transform var(--dur) var(--ease);
}

.on .thumb {
  transform: translateX(16px);
}

.track:disabled:not(.loading) {
  cursor: not-allowed;
  background: rgba(var(--rgb-brand-deep), 0.07);
  box-shadow: inset 0 0 0 1px rgba(var(--rgb-brand-deep), 0.08);
}

.on:disabled:not(.loading) {
  background: rgba(var(--rgb-brand-deep), 0.22);
}

.loading {
  cursor: progress;
}

.text {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding-top: 2px;
}

.label {
  font-size: var(--text-body);
  font-weight: 700;
  color: var(--ink-body);
  cursor: pointer;
}

.description {
  font-size: var(--text-caption);
  color: var(--ink-muted);
}

.disabled .label,
.disabled .description {
  color: var(--ink-disabled);
  cursor: not-allowed;
}

"use client";

import { useId, type ReactNode } from "react";
import { cx } from "../_internal/cx";
import { Spinner } from "../Spinner/Spinner";
import styles from "./Switch.module.css";

export type SwitchProps = {
  checked: boolean;
  onChange: (checked: boolean) => void;
  label: ReactNode;
  description?: ReactNode;
  disabled?: boolean;
  /** The change is saving. Blocks input and shows a spinner in the thumb. */
  loading?: boolean;
  id?: string;
  /** Label on the left, switch pushed right: for settings rows. */
  labelPosition?: "start" | "end";
  className?: string;
};

/**
 * For settings that apply immediately. A choice that is submitted with a form
 * is a Checkbox, not a Switch. Track is a rounded rectangle with a concentric
 * thumb (8px outer, 3px inset, 5px thumb): no capsules.
 */
export function Switch({
  checked,
  onChange,
  label,
  description,
  disabled,
  loading,
  id: idProp,
  labelPosition = "end",
  className,
}: SwitchProps) {
  const autoId = useId();
  const id = idProp ?? `switch-${autoId}`;
  const labelId = `${id}-label`;
  const descId = description ? `${id}-desc` : undefined;

  return (
    <div data-slot="switch" className={cx(styles.root, labelPosition === "start" && styles.start, disabled && styles.disabled, className)}>
      <button
        id={id}
        type="button"
        role="switch"
        aria-checked={checked}
        aria-labelledby={labelId}
        aria-describedby={descId}
        aria-busy={loading || undefined}
        disabled={disabled || loading}
        onClick={() => onChange(!checked)}
        className={cx(styles.track, checked && styles.on, loading && styles.loading)}
      >
        <span className={styles.thumb}>{loading ? <Spinner size={11} tone="brand" /> : null}</span>
      </button>
      <span className={styles.text}>
        <label id={labelId} htmlFor={id} className={styles.label}>
          {label}
        </label>
        {description ? (
          <span id={descId} className={styles.description}>
            {description}
          </span>
        ) : null}
      </span>
    </div>
  );
}
